5: import type { Significator } from './domain/Significator.js';
6: import type { ScheduledEncounter } from './domain/EncounterSpecNew.js';
7: import { scheduleNext, type WorldState, type SessionContext } from './engines/EncounterScheduler.js';
8: import { processOutcome, applyConsequences, type PlayerResponse } from './engines/ConsequenceEngine.js';
9: import { detectThreshold, advanceTransformation, commitTransformation, createInitialTransformationState, type TransformationSignal, type TransformationState } from './engines/TransformationDetector.js';
10: import { detectBleedThrough } from './engines/ThetaDecay.js';
11: import { toSnapshot } from './domain/SignificatorSnapshot.js';
12: import { computeCCI, type CCIScore } from './engines/CCIEngine.js';
13: import {
14:   generateSessionStrategy,
15:   evaluateMidSessionAdjustment,
16:   applyWeightBias,
17:   checkSafetyOverride,
18:   computePostTransformationBias,
19:   type SessionStrategy,
20:   type SessionStrategyAdjustment,
21:   type RecentEncounter,
22: } from './engines/AutoModeStrategy.js';
23: import { DEFAULT_WEIGHTS, type PriorityWeights } from './engines/PriorityComputation.js';
24: import { runModeAwareAssessment } from './assessments/engine.js';
25: import type { AssessmentResult, ShadowAssessmentResult, StageAssessment, TrialResult, ModuleExecutionMode } from './assessments/types.js';
26: 
27: export interface TickResult {
28:   readonly encounter: ScheduledEncounter | null;
29:   readonly encounters: readonly ScheduledEncounter[];
30:   readonly sig: Significator;
31:   readonly world: WorldState;
32:   readonly transformation: TransformationSignal | null;
33:   readonly bleedThrough: readonly string[];
34: }
35: 
36: export interface SessionState {
37:   readonly strategy: SessionStrategy;
38:   readonly cci: CCIScore;
39:   readonly recentOutcomes: RecentEncounter[];
40:   readonly encountersSinceRefresh: number;
41:   readonly transformationState: TransformationState;
42: }
43: 
44: /**
45:  * Initialize a new session: compute CCI, generate strategy.
46:  * Called once at session start before the first encounter.
47:  */
48: export function startSession(sig: Significator, session: SessionContext): SessionState {
49:   const snapshot = toSnapshot(sig);
50:   const cci = computeCCI(snapshot);
51:   const strategy = generateSessionStrategy(cci, session, null);
52:   return {
53:     strategy,
54:     cci,
55:     recentOutcomes: [],
56:     encountersSinceRefresh: 0,
57:     transformationState: createInitialTransformationState(),
58:   };
59: }
60: 
61: /**
62:  * Enhanced tick that uses session strategy for weight biasing.
63:  * Call this instead of tick() when auto-mode is active.
64:  *
65:  * Integrates CCI computation and mid-session adjustment logic:
66:  * 1. Applies weight bias from session strategy to priority computation
67:  * 2. Tracks encounter outcomes
68:  * 3. Every reEvaluationInterval encounters: recomputes CCI and evaluates adjustment
69:  */
70: export function tickWithStrategy(
71:   sig: Significator,
72:   world: WorldState,
73:   session: SessionContext,
74:   sessionState: SessionState,
75:   response: PlayerResponse | null,
76:   previousEncounter: ScheduledEncounter | null,
77:   now: number,
78: ): { tickResult: TickResult; sessionState: SessionState } {
79:   // 1. Process response from previous encounter (if available)
80:   let updatedSig = sig;
81:   let updatedWorld = world;
82: 
83:   if (response && previousEncounter) {
84:     const record = processOutcome(previousEncounter, response, now);
85:     const result = applyConsequences(sig, world, record, previousEncounter);
86:     updatedSig = result.sig;
87:     updatedWorld = result.world;
88:   }
89: 
90:   // 2. Increment encounter counter
91:   const encountersSinceRefresh = sessionState.encountersSinceRefresh + 1;
92: 
93:   // 3. Apply weight bias from strategy to default weights
94:   const biasedWeights: PriorityWeights = applyWeightBias(
95:     DEFAULT_WEIGHTS,
96:     sessionState.strategy.weightBias,
97:   );
98: 
99:   // 4. Check for bleed-through
100:   const bleedThrough = detectBleedThrough(updatedSig.theta.lastEncounter, now);
101: 
102:   // 5. Schedule next encounter with updated state and biased weights
103:   const scheduled = scheduleNext(updatedSig, updatedWorld, session, now, 5, biasedWeights);
104:   const encounter = scheduled[0] ?? null;
105: 
106:   // 6. Check transformation threshold and advance state machine
107:   const transformation = detectThreshold(updatedSig);
108:   let updatedTransformationState = advanceTransformation(sessionState.transformationState, updatedSig);
109:   
110:   // If transformation completes, commit it and update Significator
111:   const commitResult = commitTransformation(updatedTransformationState);
112:   if (commitResult.targetStage) {
113:     // Advance the Significator to the new stage
114:     updatedSig = {
115:       ...updatedSig,
116:       currentStage: commitResult.targetStage,
117:       transformations: [
118:         ...updatedSig.transformations,
119:         {
120:           fromStage: updatedSig.currentStage,
121:           toStage: commitResult.targetStage,
122:           triggeredAt: Date.now(),
123:           catalystCount: updatedSig.totalEncounters,
124:         },
125:       ],
126:     };
127:     updatedTransformationState = commitResult.newState;
128:   }
129: 
130:   // 7. Track outcome in recentOutcomes
131:   const quality = response ? estimateResponseQuality(response) : 0.3;
132:   const newOutcome: RecentEncounter = {
133:     outcome: response ? 'completed' : 'avoided',
134:     quality,
135:     mode: 'capacity',
136:     shadowIntegrated: false,
137:   };
138:   const recentOutcomes = [newOutcome, ...sessionState.recentOutcomes].slice(0, 20);
139: 
140:   // 8. Mid-session refresh: every reEvaluationInterval encounters
141:   const interval = sessionState.strategy.adjustmentThresholds.reEvaluationInterval;
142:   let updatedStrategy = sessionState.strategy;
143:   let updatedCCI = sessionState.cci;
144: 
145:   if (encountersSinceRefresh % interval === 0) {
146:     // Recompute CCI from current Significator state
147:     const freshSnapshot = toSnapshot(updatedSig);
148:     updatedCCI = computeCCI(freshSnapshot);
149: 
150:     // Evaluate whether mid-session adjustment is needed
151:     const adjustment = evaluateMidSessionAdjustment(
152:       updatedStrategy,
153:       session,
154:       recentOutcomes,
155:     );
156: 
157:     if (adjustment !== null) {
158:       // Apply the adjustment to strategy
159:       updatedStrategy = applyAdjustmentToStrategy(updatedStrategy, adjustment);
160:     }
161:   }
162: 
163:   // 9. Safety override: if player is in distress, force consolidation theme
164:   const snapshot = toSnapshot(updatedSig);
165:   if (checkSafetyOverride(snapshot)) {
166:     updatedStrategy = {
167:       ...updatedStrategy,
168:       theme: 'consolidation',
169:       themeRationale: 'Safety override: high fixation + unresolved shadows',
170:     };
171:   }
172: 
173:   // 10. Post-transformation bias: apply weight adjustments after recent transformation
174:   const lastTransformation = updatedSig.transformations[updatedSig.transformations.length - 1];
175:   if (lastTransformation) {
176:     const sessionsSinceTransform = updatedSig.totalSessions;
177:     const postBias = computePostTransformationBias(sessionsSinceTransform);
178:     if (postBias) {
179:       updatedStrategy = {
180:         ...updatedStrategy,
181:         weightBias: {
182:           thetaUrgency: updatedStrategy.weightBias.thetaUrgency + (postBias.thetaUrgency ?? 0),
183:           shadowActivation: updatedStrategy.weightBias.shadowActivation + (postBias.shadowActivation ?? 0),
184:           polarityAlignment: updatedStrategy.weightBias.polarityAlignment + (postBias.polarityAlignment ?? 0),
185:           transformationReadiness: updatedStrategy.weightBias.transformationReadiness + (postBias.transformationReadiness ?? 0),
186:           driveCorrection: updatedStrategy.weightBias.driveCorrection + (postBias.driveCorrection ?? 0),
187:           narrativeCoherence: updatedStrategy.weightBias.narrativeCoherence + (postBias.narrativeCoherence ?? 0),
188:           sessionFit: updatedStrategy.weightBias.sessionFit + (postBias.sessionFit ?? 0),
189:         },
190:       };
191:     }
192:   }
193: 
194:   const tickResult: TickResult = {
195:     encounter,
196:     encounters: scheduled,
197:     sig: updatedSig,
198:     world: updatedWorld,
199:     transformation,
200:     bleedThrough,
201:   };
202: 
203:   const newSessionState: SessionState = {
204:     strategy: updatedStrategy,
205:     cci: updatedCCI,
206:     recentOutcomes,
207:     encountersSinceRefresh,
208:     transformationState: updatedTransformationState,
209:   };
210: 
211:   return { tickResult, sessionState: newSessionState };
212: }
