214: /**
215:  * Apply a mid-session adjustment to the current strategy.
216:  * Returns a new strategy with the adjustment incorporated.
217:  */
218: function applyAdjustmentToStrategy(
219:   strategy: SessionStrategy,
220:   adjustment: SessionStrategyAdjustment,
221: ): SessionStrategy {
222:   let updated = { ...strategy };
223: 
224:   if (adjustment.newPeakIntensity) {
225:     updated = {
226:       ...updated,
227:       arc: {
228:         ...updated.arc,
229:         peak: {
230:           ...updated.arc.peak,
231:           intensityRange: adjustment.newPeakIntensity,
232:         },
233:       },
234:     };
235:   }
236: 
237:   if (adjustment.newTheme) {
238:     updated = { ...updated, theme: adjustment.newTheme };
239:   }
240: 
241:   if (adjustment.newWeightBias) {
242:     updated = { ...updated, weightBias: adjustment.newWeightBias };
243:   }
244: 
245:   return updated;
246: }
