248: /**
249:  * Estimate encounter quality from the richness of the player response.
250:  * Quality reflects engagement depth: diverse drive signals, shadow surfacing,
251:  * and narrative richness indicate higher engagement.
252:  */
253: function estimateResponseQuality(response: PlayerResponse): number {
254:   let quality = 0.5; // baseline for any completed encounter
255: 
256:   // Diverse drive directionality boosts quality
257:   const driveValues = Object.values(response.driveDirectionality);
258:   const uniqueDrives = new Set(driveValues).size;
259:   if (uniqueDrives >= 3) quality += 0.15;
260:   else if (uniqueDrives >= 2) quality += 0.08;
261: 
262:   // Shadow surfacing indicates deep engagement
263:   if (response.shadowSurfaced !== null) quality += 0.15;
264: 
265:   // Shadow resolution indicates integration
266:   if (response.shadowResolvedId !== null) quality += 0.1;
267: 
268:   // Longer narrative suggests deeper engagement
269:   if (response.narrativeSummary.length > 100) quality += 0.1;
270:   else if (response.narrativeSummary.length > 50) quality += 0.05;
271: 
272:   return Math.min(1.0, quality);
273: }
