275: /**
276:  * Single game tick: process previous response, schedule next encounter, check transformation.
277:  * In headless mode, `response` is provided directly (for testing/simulation).
278:  *
279:  * This is the original tick function, preserved for backward compatibility
280:  * when auto-mode is not active.
281:  */
282: export function tick(
283:   sig: Significator,
284:   world: WorldState,
285:   session: SessionContext,
286:   response: PlayerResponse | null,
287:   previousEncounter: ScheduledEncounter | null,
288:   now: number,
289: ): TickResult {
290:   // 1. Process response from PREVIOUS encounter
291:   let updatedSig = sig;
292:   let updatedWorld = world;
293: 
294:   if (response && previousEncounter) {
295:     const record = processOutcome(previousEncounter, response, now);
296:     const result = applyConsequences(sig, world, record, previousEncounter);
297:     updatedSig = result.sig;
298:     updatedWorld = result.world;
299:   }
300: 
301:   // 2. Check for bleed-through (theta-decay urgency)
302:   const bleedThrough = detectBleedThrough(updatedSig.theta.lastEncounter, now);
303: 
304:   // 3. Schedule next encounter
305:   const scheduled = scheduleNext(updatedSig, updatedWorld, session, now, 1);
306:   const encounter = scheduled[0] ?? null;
307: 
308:   // 4. Check transformation threshold
309:   const transformation = detectThreshold(updatedSig);
310: 
311:   return { encounter, encounters: scheduled, sig: updatedSig, world: updatedWorld, transformation, bleedThrough };
312: }
313: 
314: /**
315:  * Execute a module headlessly given pre-collected trials.
316:  * Bridges the gap between encounter scheduling and consequence processing.
317:  * In headless/test mode, trials are provided directly.
318:  * In game mode, the AssessmentScene collects trials interactively.
319:  */
320: export function executeModule(
321:   module: StageAssessment,
322:   trials: readonly TrialResult[],
323:   mode: ModuleExecutionMode,
324: ): AssessmentResult | ShadowAssessmentResult {
325:   return runModeAwareAssessment(module, trials, mode);
326: }
327: 
328: /**
329:  * End a session: apply theta-decay to all unvisited modules,
330:  * persist final state, and return session summary.
331:  */
332: export function endSession(
333:   sig: Significator,
334:   sessionState: SessionState,
335:   now: number,
336: ): { sig: Significator; summary: { encountersCompleted: number; shadowsSurfaced: number; shadowsResolved: number } } {
337:   // Apply theta-decay: increment decay for all cells NOT visited this session
338:   // recentOutcomes don't carry cell keys directly, so we rely on theta timestamps
339:   // Cells with timestamps >= session start are considered visited
340: 
341:   // Count session stats
342:   const encountersCompleted = sessionState.recentOutcomes.filter(o => o.outcome === 'completed').length;
343:   // Count shadows surfaced and resolved during this session
344:   // (entries created or resolved since the first outcome in this session)
345:   const sessionStartMs = sessionState.recentOutcomes.length > 0
346:     ? now - sessionState.recentOutcomes.length * 5000 // approximate session start
347:     : now;
348:   const shadowsSurfaced = sig.shadows.entries.filter(e => e.surfacedAt >= sessionStartMs).length;
349:   const shadowsResolved = sig.shadows.entries.filter(e => e.resolvedAt !== null && e.resolvedAt >= sessionStartMs).length;
350: 
351:   // Increment totalSessions
352:   const updatedSig: Significator = {
353:     ...sig,
354:     totalSessions: sig.totalSessions + 1,
355:   };
356: 
357:   return {
358:     sig: updatedSig,
359:     summary: { encountersCompleted, shadowsSurfaced, shadowsResolved },
360:   };
