1: /**
2:  * ThetaDecay — computes per-cell staleness via exponential decay.
3:  * Spec: foundations/16 §6, foundations/24 §3.2
4:  */
5: 
6: export interface ThetaParams {
7:   readonly halfLife: number; // ms — time for staleness to reach 0.5
8:   readonly bleedThreshold: number; // 0-1 — staleness above this triggers bleed-through
9: }
10: 
11: export const DEFAULT_THETA_PARAMS: ThetaParams = {
12:   halfLife: 7 * 24 * 60 * 60 * 1000, // 7 days
13:   bleedThreshold: 0.7,
14: };
15: 
16: /** Compute staleness score (0 = fresh, 1 = fully decayed) for a single cell. */
17: export function computeCellStaleness(lastEncounterMs: number, now: number, halfLife: number): number {
18:   const elapsed = now - lastEncounterMs;
19:   if (elapsed <= 0) return 0;
20:   return 1 - Math.pow(0.5, elapsed / halfLife);
21: }
22: 
23: /** Compute staleness for all cells. Key format: `${line}:${stage}` */
24: export function computeStaleness(
25:   timestamps: Readonly<Record<string, number>>,
26:   now: number,
27:   params: ThetaParams = DEFAULT_THETA_PARAMS,
28: ): Record<string, number> {
