1: /**
2:  * MacroCatalystEngine — PESTLE tension accumulation, macro-event lifecycle.
3:  * Spec: foundations/24 §8
4:  */
5: import type { Stage } from '../domain/Stage.js';
6: 
7: export interface PESTLETension {
8:   readonly political: number;
9:   readonly economic: number;
10:   readonly social: number;
11:   readonly technological: number;
12:   readonly legal: number;
13:   readonly environmental: number;
14: }
15: 
16: export interface MacroEvent {
17:   readonly id: string;
18:   readonly trigger: keyof PESTLETension;
19:   readonly altitude: Stage;
20:   readonly active: boolean;
21:   readonly sessionsActive: number;
22: }
23: 
24: export type MacroEventPhase = 'onset' | 'active' | 'resolution';
25: 
26: export interface MacroEventState {
27:   readonly event: MacroEvent;
28:   readonly phase: MacroEventPhase;
29:   readonly sessionsInPhase: number;
30:   readonly encountersSinceStart: number;
31:   readonly playerChoices: readonly string[];
32: }
33: 
34: export function createInitialTension(): PESTLETension {
35:   return { political: 0, economic: 0, social: 0, technological: 0, legal: 0, environmental: 0 };
36: }
37: 
38: /**
39:  * Accumulate tension from an encounter outcome.
40:  * Each encounter shifts one PESTLE dimension by a small delta.
41:  */
42: export function accumulateTension(
43:   tension: PESTLETension,
44:   dimension: keyof PESTLETension,
45:   delta: number,
46: ): PESTLETension {
47:   const decayed = decayTension(tension);
48:   return { ...decayed, [dimension]: Math.min(1, Math.max(0, decayed[dimension] + delta)) };
49: }
50: 
51: /**
52:  * Natural tension decay (0.01 per encounter-transition).
53:  */
54: export function decayTension(tension: PESTLETension): PESTLETension {
55:   const result = {} as Record<string, number>;
56:   for (const [k, v] of Object.entries(tension)) {
57:     result[k] = Math.max(0, v - 0.01);
58:   }
59:   return result as unknown as PESTLETension;
60: }
61: 
62: /**
63:  * Check if any dimension has crossed the macro-event threshold (0.75).
64:  */
65: export function checkMacroTrigger(tension: PESTLETension): (keyof PESTLETension) | null {
66:   for (const [k, v] of Object.entries(tension)) {
67:     if (v >= 0.75) return k as keyof PESTLETension;
68:   }
69:   return null;
70: }
71: 
72: /**
73:  * Attempt to trigger a new macro-event based on PESTLE tension.
74:  * Spec: foundations/24 §8.1
75:  * Constraints:
76:  * - Tension >= 0.75 on any dimension
77:  * - Max 2 active events simultaneously
78:  * - Event altitude must match player's centreOfGravity ± 1
79:  */
80: export function tryTriggerMacroEvent(
81:   tension: PESTLETension,
82:   activeEvents: readonly MacroEvent[],
83:   playerStage: Stage,
84:   now: number,
85: ): MacroEvent | null {
86:   if (activeEvents.length >= 2) return null;
87: 
88:   const trigger = checkMacroTrigger(tension);
89:   if (!trigger) return null;
90: 
91:   // Check minimum spacing (simplified: no event in last 10 encounters)
92:   const recentEvent = activeEvents.find(e => e.sessionsActive < 10);
93:   if (recentEvent) return null;
94: 
95:   return {
96:     id: `macro-${trigger}-${now}`,
97:     trigger,
98:     altitude: playerStage,
99:     active: true,
100:     sessionsActive: 0,
101:   };
102: }
103: 
104: /**
105:  * Advance a macro-event through its lifecycle phases.
106:  * Onset: 1-2 sessions (world signals coming event)
107:  * Active: 3-8 sessions (encounter pool modified)
108:  * Resolution: player choices determine outcome
109:  */
110: export function advanceMacroEvent(state: MacroEventState): MacroEventState {
111:   switch (state.phase) {
112:     case 'onset':
113:       if (state.sessionsInPhase >= 2) {
114:         return { ...state, phase: 'active', sessionsInPhase: 0 };
115:       }
116:       return { ...state, sessionsInPhase: state.sessionsInPhase + 1 };
117: 
118:     case 'active':
119:       if (state.sessionsInPhase >= 6 || state.playerChoices.length >= 5) {
120:         return { ...state, phase: 'resolution', sessionsInPhase: 0 };
121:       }
122:       return { ...state, sessionsInPhase: state.sessionsInPhase + 1 };
123: 
124:     case 'resolution':
125:       return state; // Terminal — resolved externally
126:   }
127: }
128: 
129: /**
130:  * Record a player choice during an active macro-event.
131:  */
132: export function recordMacroChoice(
133:   state: MacroEventState,
134:   choiceId: string,
135: ): MacroEventState {
136:   return {
137:     ...state,
138:     playerChoices: [...state.playerChoices, choiceId],
139:     encountersSinceStart: state.encountersSinceStart + 1,
140:   };
141: }
142: 
143: /**
144:  * Resolve a macro-event: reset PESTLE tension for the trigger dimension,
145:  * deactivate the event, and return the resolution outcome.
146:  */
147: export function resolveMacroEvent(
148:   state: MacroEventState,
149:   tension: PESTLETension,
150: ): { tension: PESTLETension; resolvedEvent: MacroEvent } {
151:   const resolvedEvent: MacroEvent = {
152:     ...state.event,
153:     active: false,
154:     sessionsActive: state.encountersSinceStart,
155:   };
156: 
157:   // Reset tension for the trigger dimension
158:   const newTension = { ...tension, [state.event.trigger]: 0 };
159: 
160:   return { tension: newTension, resolvedEvent };
161: }
162: 
163: /**
164:  * Get encounter pool modifications for an active macro-event.
165:  * During 'active' phase, some encounters become available and others are blocked.
166:  */
167: export function getMacroEncounterModifications(state: MacroEventState): {
168:   additionalEncounterTags: readonly string[];
169:   blockedEncounterTags: readonly string[];
170: } {
171:   if (state.phase !== 'active') {
172:     return { additionalEncounterTags: [], blockedEncounterTags: [] };
173:   }
174: 
175:   return {
