6:  * Computes a multi-dimensional composite signal capturing the Significator's
7:  * overall developmental state at session-start. Feeds the auto-mode strategy
8:  * engine (foundations/27) which shapes session-level decisions.
9:  *
10:  * The CCI is NEVER player-facing (Veil principle). It carries no normative
11:  * valence -- higher is not "better"; it is different.
12:  */
13: import type { SignificatorSnapshot } from '../domain/SignificatorSnapshot.js';
14: import type { Line } from '../domain/Line.js';
15: import type { Stage } from '../domain/Stage.js';
16: import type { Drive } from '../domain/Drive.js';
