20: 
21: // ---------------------------------------------------------------------------
22: // Types
23: // ---------------------------------------------------------------------------
24: 
25: export interface CCIWeights {
26:   altitude: number;
27:   driveHealth: number;
28:   polarity: number;
29:   shadowTopology: number;
30:   transformationReadiness: number;
31: }
