41: export type SessionTheme =
42:   | 'consolidation'
43:   | 'growth-edge-push'
44:   | 'shadow-integration'
45:   | 'drive-rebalancing'
46:   | 'transformation-prep'
47:   | 'active-transformation'
48:   | 'post-transformation'
49:   | 'polarity-deepening'
