53: export type TransformationProximity = 'distant' | 'approaching' | 'imminent' | 'active';
54: 
55: export interface PolaritySessionGuidance {
56:   mode: 'exploration' | 'crystallizing' | 'crystallized';
57:   recommendedDiversity: number;
58:   temptationFrequency: number;
59: }
