61: export interface CCISessionSignals {
62:   recommendedTheme: SessionTheme;
63:   intensityBudget: number;
64:   shadowPressure: ShadowPressureLevel;
65:   transformationProximity: TransformationProximity;
66:   driveRebalancingTarget: Drive | null;
67:   polarityGuidance: PolaritySessionGuidance;
68: }
