70: export interface CCIScore {
71:   composite: number;
72:   dimensions: {
73:     altitude: number;
74:     driveHealth: number;
75:     polarity: number;
76:     shadowTopology: number;
77:     transformationReadiness: number;
78:   };
79:   weights: CCIWeights;
80:   dominantDimension: keyof CCIWeights;
81:   sessionSignals: CCISessionSignals;
82: }
