84: // ---------------------------------------------------------------------------
85: // Internal dimension input interfaces
86: // ---------------------------------------------------------------------------
87: 
88: export interface AltitudeInput {
89:   perLineAltitudes: Record<Line, Stage>;
90:   centreOfGravity: Stage;
91:   spread: number;
92:   lowestAltitude: Stage;
93:   highestAltitude: Stage;
94:   linesAtEdge: number;
95: }
