97: export interface DriveHealthInput {
98:   balance: Record<Drive, number>;
99:   fixationRisk: Record<Drive, number>;
100:   maxImbalance: number;
101:   maxFixationRisk: number;
102:   complementaryTension: {
103:     agencyVsCommunion: number;
104:     erosVsAgape: number;
105:   };
106: }
