108: export interface PolarityInput {
109:   masterMode: 'exploration' | 'crystallizing' | 'crystallized';
110:   crystallizationIndex: number;
111:   exploratoryBreadth: number;
112:   coherentLineCount: number;
113:   recentPolarityStability: number;
114: }
