116: export interface ShadowTopologyInput {
117:   unresolvedCount: number;
118:   averageSeverity: number;
119:   maxSeverity: number;
120:   compoundPatternCount: number;
121:   recentSurfacingRate: number;
122:   integrationRate: number;
123:   oldestUnresolvedAge: number;
124: }
125: 
126: export interface TransformationReadinessInput {
127:   linesAtEdge: number;
128:   shadowClearance: boolean;
129:   catalystSaturation: number;
130:   pendingTransformation: boolean;
131:   targetStage: Stage | null;
132:   sessionsSinceLastTransformation: number;
133: }
134: 
135: interface CCIDimensionInputs {
136:   altitude: AltitudeInput;
137:   driveHealth: DriveHealthInput;
138:   polarity: PolarityInput;
