288:   public async run(): Promise<OrchestratorResult> {
289:     const [line, stage] = this.encounter.moduleRef.split(':') as [Line, Stage];
290:     const now = Date.now();
291: 
292:     // If noLlm flag is set, skip LLM entirely and go directly to fallback
293:     if (this.noLlm) {
294:       return this.runFallback(line, stage, now);
295:     }
296: 
297:     // G.2: Language-Reflective modality gets a special LLM-driven assessment path
298:     // This produces genuine open-ended dialogue scoring instead of MCQ wrapping
299:     if (this.encounter.modality === 'LanguageReflective') {
300:       return this.runLanguageReflective(line, stage, now);
301:     }
302: 
303:     // 1. Build context system prompt
304:     const continuityContext = this.buildContinuityContext();
305:     const contextInput = {
306:       encounter: this.encounter,
307:       significator: this.significator,
308:       holonRegistry: { holons: this.world.holons },
309:       conceptIndex: this.conceptIndex,
310:       recentConsequences: this.history,
311:       sessionContext: { energy: 'high' as const },
312:     };
313:     const context = buildContext(contextInput);
314: 
315:     // Build assessment module context for the LLM
316:     const assessmentContext = this.module ? this.buildAssessmentContext(this.module) : '';
317: 
318:     let shadowContext = '';
319:     if (this.encounter.executionMode === 'shadow') {
320:       const [shadowLine, shadowStage] = this.encounter.moduleRef.split(':') as [Line, Stage];
321:       const { generateShadowContent, buildShadowPromptSuffix } = await import('../engines/ShadowContentGenerator.js');
322:       const shadowContent = generateShadowContent(shadowLine, shadowStage, this.encounter.shadowTarget);
323:       
324:       const unresolvedShadows = this.significator.shadows.entries.filter(
325:         (e: { line: string; resolvedAt: number | null }) => e.line === shadowLine && e.resolvedAt === null
326:       ).length;
327:       
328:       shadowContext = buildShadowPromptSuffix(shadowContent, shadowLine, shadowStage, unresolvedShadows);
329:     }
330: 
331:     const systemPrompt = `${context.systemPrompt}${assessmentContext}${continuityContext}${shadowContext}
332: [AGENT RULES]
333: 1. You are the Agentic Game Master driving this developmental encounter.
334: 2. Present the encounter situationally and narratively. If you need to present stimuli, choices, or ask questions, ALWAYS call the 'ask_user_question' tool. Do not ask questions in raw text responses.
335: 3. Every ask_user_question call MUST include exactly 4 MCQ options AND set allowWriteIn=true for a 5th manual write-in option. Label the write-in option clearly (e.g., "Other (describe in your own words)").
336: 4. Keep the flow interactive, building upon prior answers.
337: 5. This encounter has a budget of 2 exchanges. After the player has responded to 2 questions, you MUST call 'complete_encounter'. Do NOT generate more than 2 ask_user_question calls.
338: 6. When calling 'complete_encounter', evaluate the player per the DRIVE PROBES section. Score each drive independently. Provide driveScores (0.0-1.0 per drive) and driveSignals (pathology enum per drive).
339: 7. If RECENT ENCOUNTERS are listed, reference them subtly — the player's journey has continuity.`;
340: 
341:     if (this.messages.length === 0) {
342:       this.messages.push({
343:         role: 'user',
344:         content: `Start the encounter: ${this.encounter.id} (${line} - ${stage}). Introduce the scene and ask the first question.`
345:       });
346:     }
347: 
348:     let loopCount = 0;
349:     const maxLoops = 10; // Safety guard
350:     let askCount = 0; // Track ask_user_question calls for budget enforcement
351: 
352:     while (loopCount < maxLoops) {
353:       loopCount++;
354: 
355:       // Request next turn from LLM
356:       const res = await queryLLMWithTools(systemPrompt, this.messages, TOOLS);
357: 
358:       // Detect LLM unavailability on first call — switch to fallback
359:       if (loopCount === 1 && res.content && res.content.trim().startsWith('{"error"') && (!res.toolCalls || res.toolCalls.length === 0)) {
360:         return this.runFallback(line, stage, now);
361:       }
362: 
363:       const assistantMsg: AgentMessage = {
364:         role: 'assistant',
365:         content: res.content,
366:         toolCalls: res.toolCalls,
367:       };
368:       this.messages.push(assistantMsg);
369: 
370:       if (res.toolCalls && res.toolCalls.length > 0) {
371:         // Execute tool calls
372:         for (const tc of res.toolCalls) {
373:           if (tc.function.name === 'ask_user_question') {
374:             askCount++;
375:             const params = JSON.parse(tc.function.arguments) as AskUserQuestionParams;
376:             
377:             // Present to UI (Phaser or CLI)
378:             const result = await this.uiHandler.askUser(params);
379: 
380:             // Record tool response
381:             this.messages.push({
382:               role: 'tool',
383:               content: JSON.stringify(result),
384:               toolCallId: tc.id,
385:               name: 'ask_user_question'
386:             });
387: 
388:             // Budget enforcement: after 2 exchanges, force complete_encounter
389:             if (askCount >= 2 && !res.toolCalls.some(t => t.function.name === 'complete_encounter')) {
390:               this.messages.push({
391:                 role: 'user',
392:                 content: 'The encounter budget of 2 exchanges is exhausted. You MUST now call complete_encounter with your evaluation of the player. Do NOT ask another question.'
393:               });
394:             }
395:           } else if (tc.function.name === 'complete_encounter') {
396:             const params = JSON.parse(tc.function.arguments) as {
397:               passed: boolean;
398:               scores?: Partial<Record<MeasureDimension, number>>;
399:               driveScores: { agency: number; communion: number; eros: number; agape: number };
400:               driveSignals: { agency: string; communion: string; eros: string; agape: string };
401:               feedback: string;
402:               polarityDirection: 'sto' | 'sts' | 'neutral';
403:               shadowSignal?: {
404:                 quadrant: ShadowQuadrant;
405:                 intensity: number;
406:               };
407:               narrativeSummary: string;
408:             };
409: 
410:             // Process completion with per-drive scores
411:             const finalResult = this.createAssessmentResult(params.passed, params.scores || {}, params.driveScores);
412:             const outcome = this.finalizeEncounter(params, now);
413: 
414:             return {
415:               ...outcome,
416:               finalResult,
417:               messages: this.messages,
418:             };
419:           }
420:         }
421:       } else {
422:         // Fallback: If assistant didn't call any tools, prompt it to proceed
423:         this.messages.push({
424:           role: 'user',
425:           content: 'Continue with the encounter. If the encounter is complete, call complete_encounter. Otherwise, call ask_user_question.'
426:         });
427:       }
428:     }
429: 
430:     // Safety fallback termination if we loop too many times
431:     const fallbackParams = {
432:       passed: true,
433:       feedback: 'Encounter completed via timeout.',
434:       polarityDirection: 'neutral' as const,
435:       narrativeSummary: `The player successfully navigated the challenge of ${this.encounter.moduleRef}.`,
436:     };
437:     const finalResult = this.createAssessmentResult(true, {});
438:     const outcome = this.finalizeEncounter(fallbackParams, now);
439: 
440:     return {
441:       ...outcome,
442:       finalResult,
443:       messages: this.messages,
444:     };
445:   }
