717:   /**
718:    * Module-aware fallback: uses the assessment module's tasks, drive probes,
719:    * and scoring rubric to present a real developmental assessment even without the LLM.
720:    * Selects a task matching the encounter modality, presents it as a narrative challenge,
721:    * evaluates the response against drive probes, detects shadow patterns,
722:    * and computes altitude progression.
723:    */
724:   private async runModuleAssessment(_line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
725:     const module = this.module!;
726:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
727:     const holonName = holon?.name ?? 'A presence';
728:     const currentModality = this.encounter.modality;
729: 
730:     // 1. Select the best task from the module based on modality
731:     const task = this.selectTaskForModality(module, currentModality);
732:     // Track the actual presented task for narrative building (fix B.2)
733:     this._currentPresentedTask = task;
734: 
735:     // 2. Present the task as a narrative challenge via uiHandler
736:     const askResult = await this.presentModuleTask(module, task, currentModality, holonName);
737:     const answer = askResult.answers[0];
738:     const rawLabel = answer?.selectedLabels[0] ?? '';
739:     const writeIn = answer?.writeInValue;
740:     const playerResponseText = writeIn ?? rawLabel;
741: 
742:     // 3. Evaluate using the TaskRenderer's evaluate() if available (produces TrialResult with timing/accuracy)
743:     //    Fall back to drive-probe evaluation if no renderer evaluate is available
744:     const endTimeMs = Date.now();
745:     let evaluation: {
746:       passed: boolean;
747:       polarityDirection: 'sto' | 'sts' | 'neutral';
748:       driveScores: { agency: number; communion: number; eros: number; agape: number };
749:       driveSignals: { agency: string; communion: string; eros: string; agape: string };
750:       feedback: string;
751:     };
752:     let trialResult: TrialResult | null = null;
753: 
754:     if (this._currentRendererEvaluate) {
755:       // Use the TaskRenderer's evaluate function for real scoring
756:       trialResult = this._currentRendererEvaluate(playerResponseText, this._currentTaskStartTime, endTimeMs);
757: 
758:       // Extract drive metadata from the trial's rawResponse (set by TaskRenderers)
759:       const rawResp = trialResult?.rawResponse as any;
760:       const matchedDrive: string | null = rawResp?.matchedDrive ?? null;
761:       const matchedPolarity: string = rawResp?.matchedPolarity ?? 'neutral';
762:       const correctnessScore: number = rawResp?.correctnessScore ?? 0.5;
763: 
764:       // Use correctnessScore as the primary scoring signal (from TaskRenderer options)
765:       const baseScore = Math.min(1, Math.max(0, correctnessScore));
766: 
767:       // D.9: Use shared shadow keyword detection helper (DRY)
768:       let writeInDriveDetection: { drive: string; polarity: string; shadowKeyword: string | null } | null = null;
769:       if (writeIn) {
770:         writeInDriveDetection = AgenticOrchestrator.detectWriteInShadow(writeIn);
771:       }
772: 
773:       // When a write-in is present, its keyword-based detection takes priority over
774:       // the renderer's label matching (which can false-positive on short words like 'I').
775:       const effectiveDrive = writeInDriveDetection?.drive ?? matchedDrive ?? null;
776:       const effectivePolarity = writeInDriveDetection?.polarity ?? (matchedPolarity !== 'neutral' ? matchedPolarity : 'neutral');
777: 
778:       // Build differentiated drive scores:
779:       // - The matched/driven drive gets the full baseScore (or boosted for write-in depth)
780:       // - Other drives get baseline neutral (0.5)
781:       // - For write-ins with no shadow detection, apply a depth boost and distribute evenly
782:       const isWriteInWithNoShadow = matchedDrive === null && !writeInDriveDetection && !!writeIn;
783: 
784:       // ── SCORING FIX: Use rubric dimension weights on TrialResult dimensions ──
785:       // OLD: averaged 4 drives → compressed to ~0.55 always, even correct answers failed at threshold 0.6
786:       // NEW: compute weighted score from TrialResult dimensions using the module's rubric weights.
787:       // This gives a true performance signal: correct MCQ → ~0.8, partial → ~0.55, wrong → ~0.25.
788:       const rubricWeights = module.scoringRubric.dimensionWeights;
789:       const trialDims = trialResult!.dimensions;
790:       let weightedSum = 0;
791:       let totalWeight = 0;
792:       for (const [dim, weight] of Object.entries(rubricWeights)) {
793:         const val = trialDims[dim as keyof typeof trialDims];
794:         if (weight && typeof val === 'number') {
795:           weightedSum += val * weight;
796:           totalWeight += weight;
797:         }
798:       }
799:       // Blend the rubric-weighted score with the drive-correctness score for a robust signal
800:       const rubricScore = totalWeight > 0 ? weightedSum / totalWeight : baseScore;
801:       const blendedScore = rubricScore * 0.6 + baseScore * 0.4;
802: 
803:       // Drive scores: matched drive gets blendedScore (consistent with pass/fail),
804:       // write-in depth bonus applied on top. Unmatched drives get a lower baseline.
805:       const matchedScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
806:       const driveScores = {
807:         agency: effectiveDrive === 'agency' ? matchedScore
808:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
809:           : matchedScore,
810:         communion: effectiveDrive === 'communion' ? matchedScore
811:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
812:           : matchedScore,
813:         eros: effectiveDrive === 'eros' ? matchedScore
814:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
815:           : matchedScore,
816:         agape: effectiveDrive === 'agape' ? matchedScore
817:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
818:           : matchedScore,
819:       };
820: 
821:       // Determine polarity from the effective drive detection
822:       const polarityDirection = effectivePolarity === 'sts' ? 'sts' as const
823:         : effectivePolarity === 'sto' ? 'sto' as const
824:         : 'neutral' as const;
825: 
826:       // Derive drive signals from the expression pattern.
827:       // IMPORTANT: Shadow signals ONLY come from write-in keyword detection or forceShadow.
828:       // A wrong MCQ answer (low correctnessScore) is a performance miss, NOT a shadow expression.
829:       const shadowFromWriteIn = writeInDriveDetection?.shadowKeyword ?? null;
830:       const driveSignals = {
831:         agency: effectiveDrive === 'agency'
832:           ? (shadowFromWriteIn === 'DarkAddicted' ? 'DarkAddicted' : 'HealthyBalanced')
833:           : 'HealthyBalanced',
834:         communion: effectiveDrive === 'communion'
835:           ? (shadowFromWriteIn === 'DarkAverted' ? 'DarkAverted' : 'HealthyBalanced')
836:           : 'HealthyBalanced',
837:         eros: effectiveDrive === 'eros'
838:           ? (shadowFromWriteIn === 'GoldenAddicted' ? 'GoldenAddicted' : 'HealthyBalanced')
839:           : 'HealthyBalanced',
840:         agape: effectiveDrive === 'agape'
841:           ? (shadowFromWriteIn === 'GoldenAverted' ? 'GoldenAverted' : 'HealthyBalanced')
842:           : 'HealthyBalanced',
843:       };
844: 
845:       // Determine pass: blendedScore must meet threshold AND no shadow pathology
846:       const passThreshold = module.scoringRubric.passThreshold ?? 0.5;
847:       const effectiveScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
848:       const hasShadow = !!shadowFromWriteIn;
849:       const passed = !hasShadow && effectiveScore >= passThreshold;
850: 
851:       // Build contextual developmental feedback based on score, drive, polarity, and history
852:       const driveLabel = effectiveDrive ?? 'unidentified';
853:       const polarityLabel = effectivePolarity === 'sts' ? 'self-oriented' : effectivePolarity === 'sto' ? 'other-oriented' : 'balanced';
854:       const scorePct = (baseScore * 100).toFixed(0);
855:       const historyCount = this.history.length;
856:       const recentPasses = this.history.slice(-3).filter(r => Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced')).length;
857:       const consistencyNote = recentPasses >= 3 ? ' You are building strong momentum across encounters.'
858:         : recentPasses === 0 && historyCount >= 2 ? ' The last few encounters have been challenging — this is where real growth happens.'
859:         : '';
860: 
861:       const feedback = hasShadow
862:         ? `A ${shadowFromWriteIn} pattern surfaced through your ${driveLabel} expression (${polarityLabel}). In the developmental framework, this shadow arises when the ${driveLabel} drive becomes imbalanced — either clinging to lower patterns (dark) or bypassing toward higher without integration (golden). Naming it here is the first step toward healing it. ${historyCount > 0 ? `This is your ${historyCount + 1}th encounter — each shadow surfaced is an opportunity for the field to work with you.` : ''}`
863:         : passed
864:           ? `Your ${driveLabel} drive expressed with health (performance: ${scorePct}%, polarity: ${polarityLabel}). ${parseInt(scorePct) >= 80 ? 'Strong performance — the integration is deepening across the ' + module.line.toLowerCase() + ' dimension.' : 'Solid engagement — the ' + module.line.toLowerCase() + ' capacity at ' + module.stage + ' stage is growing.'} ${consistencyNote}The field recognizes your sustained attention to this developmental edge.`
865:           : `Your ${driveLabel} drive expressed at ${scorePct}% performance (${polarityLabel}). ${parseInt(scorePct) >= 40 ? 'Close to the threshold — the gap between where you are and where this capacity can be is narrowing. A focused effort on the next encounter may tip the balance.' : 'This is a genuine edge for you. The ' + module.line.toLowerCase() + ' line at ' + module.stage + ' stage is where your developmental work lives right now — not as punishment, but as invitation.'} The ${module.line.toLowerCase()} dimension will continue to offer opportunities to strengthen this capacity.`;
866: 
867:       evaluation = {
868:         passed,
869:         polarityDirection,
870:         driveScores,
871:         driveSignals,
872:         feedback,
873:       };
874:     } else {
875:       // Fallback: keyword-based evaluation
876:       evaluation = this.evaluateViaDriveProbes(module, playerResponseText);
877:     }
878: 
879:     // 4. Detect shadow surfacing from response pattern (with optional forceShadow override)
880:     const validQuadrants = ['DarkAddiction', 'DarkAllergy', 'GoldenAddiction', 'GoldenAllergy'] as const;
881:     const forcedQuadrant = this.forceShadow && validQuadrants.includes(this.forceShadow as any)
882:       ? this.forceShadow as ShadowQuadrant
883:       : null;
884:     // Shadow detection only fires for write-in text (free-form responses)
885:     // MCQ option labels should NOT trigger shadow detection — they're structured choices, not expressions.
886:     const isWriteIn = !!writeIn;
887:     const shadowSignal = forcedQuadrant
888:       ? { quadrant: forcedQuadrant, intensity: 0.7 }
889:       : this.detectShadowFromResponse(playerResponseText, currentModality, isWriteIn);
890: 
891:     // If forceShadow is active, propagate to drive signals AND force-fail the encounter
892:     if (forcedQuadrant && this._currentRendererEvaluate) {
893:       const forcedDrive = forcedQuadrant === 'DarkAddiction' ? 'agency'
894:         : forcedQuadrant === 'DarkAllergy' ? 'communion'
895:         : forcedQuadrant === 'GoldenAddiction' ? 'eros'
896:         : 'agape';
897:       const forcedSignal = forcedQuadrant;
898:       evaluation.driveSignals = { ...evaluation.driveSignals, [forcedDrive]: forcedSignal } as typeof evaluation.driveSignals;
899:       // Forced shadow = pathology detected → must fail
900:       evaluation = { ...evaluation, passed: false, feedback: `Shadow surfaced: ${forcedQuadrant} through ${forcedDrive} expression (forced). This indicates the ${forcedDrive} drive is operating from a developmental shadow — awareness of this pattern is the first step toward integration.` };
901:     }
902: 
903:     // 5. Build a rich narrative summary from the module context
904:     // Pass the actual presented task so narrative matches what the user saw
905:     const narrativeSummary = this.buildModuleNarrative(module, playerResponseText, evaluation.passed, currentModality, holonName, task);
906: 
907:     // 6. Check for altitude shift: only when ALL drives HealthyBalanced AND passed
908:     const altitudeShift = this.computeAltitudeShift(evaluation.driveSignals, module, stage, evaluation.passed);
909: 
910:     const finalResult = this.createAssessmentResult(
911:       evaluation.passed, {}, evaluation.driveScores, trialResult ? [trialResult] : undefined,
912:     );
913: 
914:     // Build outcome with altitude shift support
915:     const energeticDirection: EnergeticDirection = evaluation.polarityDirection === 'sto' ? 'Radiative'
916:       : evaluation.polarityDirection === 'sts' ? 'Absorptive' : 'Diffuse';
917: 
918:     const SIGNAL_MAP: Record<string, DriveDirectionality> = {
919:       'HealthyBalanced': 'HealthyBalanced',
920:       'DarkAddicted': 'DarkAddicted',
921:       'DarkAverted': 'DarkAverted',
922:       'GoldenAddicted': 'GoldenAddicted',
923:       'GoldenAverted': 'GoldenAverted',
924:     };
925: 
926:     const baseDir: DriveDirectionality = evaluation.passed ? 'HealthyBalanced' : 'DarkAddicted';
927:     const driveDirectionality: Record<Drive, DriveDirectionality> = {
928:       Agency: SIGNAL_MAP[evaluation.driveSignals.agency] ?? baseDir,
929:       Communion: SIGNAL_MAP[evaluation.driveSignals.communion] ?? baseDir,
930:       Eros: SIGNAL_MAP[evaluation.driveSignals.eros] ?? baseDir,
931:       Agape: SIGNAL_MAP[evaluation.driveSignals.agape] ?? baseDir,
932:     };
933: 
934:     const response: PlayerResponse = {
935:       encounterId: this.encounter.id,
936:       energeticDirection,
937:       driveDirectionality: driveDirectionality as Record<Drive, DriveDirectionality>,
938:       stageOrientation: evaluation.polarityDirection === 'sto' ? 'ReachingHigher' : 'Homeostatic',
939:       sourceOfNourishment: evaluation.polarityDirection === 'sto' ? 'HigherRealm'
940:         : (evaluation.polarityDirection === 'sts' ? 'LowerRealm' : 'Ambivalent'),
941:       shadowSurfaced: shadowSignal?.quadrant ?? null,
942:       shadowResolvedId: null,
943:       narrativeSummary,
944:     };
945: 
946:     const record = processOutcome(this.encounter, response, now);
947: 
948:     // Override altitudeShift on the record if computed
949:     const updatedRecord: ConsequenceRecord = {
