118:   override update(): void {
119:     const speed = 3;
120:     if (this.cursors) {
121:       if (this.cursors.left.isDown) this.player.x -= speed;
122:       if (this.cursors.right.isDown) this.player.x += speed;
123:       if (this.cursors.up.isDown) this.player.y -= speed;
124:       if (this.cursors.down.isDown) this.player.y += speed;
125:     }
126:     if (this.isDragging) {
127:       const dx = this.dragTarget.x - this.player.x;
128:       const dy = this.dragTarget.y - this.player.y;
129:       const dist = Math.sqrt(dx * dx + dy * dy);
130:       if (dist > 5) { this.player.x += (dx / dist) * speed; this.player.y += (dy / dist) * speed; }
131:     }
132:     const { width, height } = this.scale;
133:     this.player.x = Phaser.Math.Clamp(this.player.x, 40, width - 40);
134:     this.player.y = Phaser.Math.Clamp(this.player.y, 100, height - 40);
