148:   private placeEncounterNodes(sig: Significator | undefined, world: WorldState | undefined): void {
149:     if (!sig || !world) return;
150: 
151:     const session = this.buildSessionContext(sig);
152:     const now = Date.now();
153: 
154:     // Check for existing session state (returning from encounter)
155:     const existingSessionState = this.registry.get(RegistryKeys.SessionState) as SessionState | undefined;
156: 
157:     if (existingSessionState) {
158:       // Returning from encounter: use tickWithStrategy to get biased scheduling
159:       const result = tickWithStrategy(sig, world, session, existingSessionState, null, null, now);
160:       this.sessionState = result.sessionState;
161: 
162:       // Advance transformation state machine (once per session tick)
163:       const ts = result.tickResult.sig.transformationPhase ?? 'idle';
164:       const transformationState = { phase: ts, targetStage: null, sessionsInPhase: 0, knotsResolved: 0, totalKnots: 0 };
165:       const advanced = advanceTransformation(transformationState, result.tickResult.sig);
166:       if (advanced.phase !== ts) {
167:         // Phase changed — update significator
168:         const updatedSig = { ...result.tickResult.sig, transformationPhase: advanced.phase };
169:         this.registry.set(RegistryKeys.Significator, updatedSig);
170:       }
171: 
172:       // Use the biased encounter from the pipeline
173:       const biasedEncounter = result.tickResult.encounter;
174:       const biasedWeights = applyWeightBias(DEFAULT_WEIGHTS, this.sessionState.strategy.weightBias);
175:       const encounters = biasedEncounter
176:         ? [biasedEncounter, ...scheduleNext(result.tickResult.sig, world, session, now, 4, biasedWeights)]
177:         : scheduleNext(result.tickResult.sig, world, session, now, 5, biasedWeights);
178: 
179:       this.placeNodes(encounters);
180:       this.registry.set(RegistryKeys.SessionState, this.sessionState);
181:     } else {
182:       // Fresh session: initialize CCI → AutoMode pipeline
183:       this.sessionState = startSession(sig, session);
184:       const biasedWeights = applyWeightBias(DEFAULT_WEIGHTS, this.sessionState.strategy.weightBias);
185:       const encounters = scheduleNext(sig, world, session, now, 5, biasedWeights);
186:       this.placeNodes(encounters);
187:       this.registry.set(RegistryKeys.SessionState, this.sessionState);
188:     }
189:   }
190: 
191:   /** Build SessionContext enriched with EcologicalTracker signals */
192:   private buildSessionContext(sig: Significator): SessionContext {
193:     const signals = this.ecological.getSignals();
194: 
195:     // Map movement entropy + dwell time → inferred energy
196:     let inferredEnergy: 'high' | 'moderate' | 'low' = 'moderate';
197:     if (signals.dwellTime > 2000 && signals.movementEntropy < 0.3) {
198:       inferredEnergy = 'low';
199:     } else if (signals.dwellTime < 800 && signals.movementEntropy > 0.6) {
200:       inferredEnergy = 'high';
201:     }
202: 
203:     // Map avoidance patterns → patience signals
204:     const avoidanceRate = 1 - signals.approachRate;
205: 
206:     return {
207:       encountersSoFar: sig.totalEncounters,
208:       sessionDurationMs: 0,
209:       targetSessionLength: 10,
210:       recentLines: [],
211:       inferredEnergy,
212:       patienceSignals: {
213:         avoidanceRate,
214:         responseLatencyTrend: 'stable',
215:         earlyExits: 0,
216:       },
217:     };
218:   }
