220:   /** Place encounter nodes on the map */
221:   private placeNodes(encounters: readonly ScheduledEncounter[]): void {
222:     if (encounters.length === 0) {
223:       this.add.text(this.scale.width / 2, this.scale.height / 2 + 80, 'The world is quiet...', {
224:         fontSize: '21px', color: '#555555', fontFamily: 'monospace',
225:       }).setOrigin(0.5).setDepth(5).setAlpha(0.7);
226:       return;
227:     }
228: 
229:     const { width, height } = this.scale;
230:     encounters.forEach((enc, i) => {
231:       const angle = (i / encounters.length) * Math.PI * 2 + 0.3;
232:       const radius = Math.min(width, height) * 0.28;
233:       const cx = width / 2 + Math.cos(angle) * radius;
234:       const cy = height / 2 + Math.sin(angle) * radius * 0.6;
235:       this.createEncounterNode(cx, cy, enc);
236:     });
237:     this.ecological.recordEncounterAvailable(encounters.length);
238:   }
239: 
240:   private createEncounterNode(x: number, y: number, enc: ScheduledEncounter): void {
241:     const theme = MODALITY_THEME[enc.modality];
242:     let marker: Phaser.GameObjects.Shape;
243: 
244:     switch (enc.modality) {
245:       case 'Strategic':
246:         marker = this.add.rectangle(x, y, 28, 18, theme.color, 0.7);
247:         break;
248:       case 'SocialCooperative': {
249:         // Cluster of small circles
250:         const c = this.add.circle(x, y, 6, theme.color, 0.7);
251:         this.add.circle(x - 10, y + 6, 5, theme.color, 0.5);
252:         this.add.circle(x + 10, y + 6, 5, theme.color, 0.5);
253:         marker = c;
254:         break;
255:       }
256:       default:
257:         marker = this.add.circle(x, y, 14, theme.color, enc.modality === 'ImmersiveRPG' ? 0.3 : 0.7);
258:     }
259: 
260:     marker.setDepth(5).setInteractive(
261:       new Phaser.Geom.Circle(0, 0, 20), Phaser.Geom.Circle.Contains
262:     );
263:     marker.on('pointerdown', () => {
264:       this.ecological.recordEncounterApproached(enc.modality);
265:       // Route to the correct scene based on modality
266:       const targetScene = routeModality(enc.modality);
267:       fadeToScene(this, targetScene, { encounter: enc } as Record<string, unknown>);
268:     });
269: 
270:     // Label
271:     this.add.text(x, y + 20, theme.label, {
272:       fontSize: '16px', color: '#999999', fontFamily: 'monospace',
273:     }).setOrigin(0.5).setDepth(5);
274: 
275:     // Subtle animation
276:     this.tweens.add({
277:       targets: marker,
278:       alpha: enc.modality === 'ImmersiveRPG' ? { from: 0.2, to: 0.4 } : { from: 0.6, to: 1 },
279:       scaleX: enc.modality === 'Embodied' ? 1.15 : 1.05,
280:       scaleY: enc.modality === 'Embodied' ? 1.15 : 1.05,
281:       duration: enc.modality === 'LanguageReflective' ? 400 : 800,
282:       yoyo: true,
283:       repeat: -1,
284:       ease: 'Sine.easeInOut',
285:     });
286:   }
287: 
288:   /** End the current session and return to MainMenu */
289:   private leaveWorld(): void {
290:     const sig = this.registry.get(RegistryKeys.Significator) as Significator | undefined;
291:     const sessionState = this.registry.get(RegistryKeys.SessionState) as SessionState | undefined;
292:     if (sig && sessionState) {
293:       const now = Date.now();
294:       const ended = endSession(sig, sessionState, now);
295:       this.registry.set(RegistryKeys.Significator, ended.sig);
296:       this.registry.remove(RegistryKeys.SessionState);
297:       // Persist the updated state
298:       const saveRepo = this.registry.get(RegistryKeys.SaveRepo) as SaveRepository | undefined;
299:       if (saveRepo) {
300:         void saveRepo.saveProfile(ended.sig).catch(() => {});
301:       }
302:       // Emit session ended event
303:       const eventBus = this.registry.get(RegistryKeys.EventBus) as EventBus | undefined;
304:       if (eventBus) {
305:         eventBus.emit('session_ended', { timestamp: now, encounterCount: ended.summary.encountersCompleted });
306:       }
307:     }
308:     fadeToScene(this, SceneKeys.MainMenu);
309:   }
310: 
