312:     const { width, height } = this.scale;
313:     const g = this.add.graphics();
314: 
315:     // Deep volcanic background
316:     g.fillStyle(0x1a0a0a);
317:     g.fillRect(0, 0, width, height);
318: 
319:     // Layered volcanic rock strata
320:     g.fillStyle(0x2a0505, 0.5);
